#include "bundled_font_blobs.hpp"

#include <array>

#include "pulp-bundled-fonts_data.hpp" // Generated by pulp_add_binary_data.

namespace pulp::canvas::detail {

// One entry per .ttf listed in core/canvas/CMakeLists.txt. Keep this list and
// the CMake SOURCES list in sync; there is intentionally no auto-discovery, so
// a mismatch is a link error rather than a silent runtime miss.
std::span<const BundledBlob> bundled_font_blobs() {
    static const std::array<BundledBlob, 6> kBlobs = {{
        {"Inter-Regular.ttf", pulp_bundled_fonts::Inter_Regular_ttf,
         pulp_bundled_fonts::Inter_Regular_ttf_size},
        {"JetBrainsMono-Regular.ttf", pulp_bundled_fonts::JetBrainsMono_Regular_ttf,
         pulp_bundled_fonts::JetBrainsMono_Regular_ttf_size},
        {"Jost-Regular.ttf", pulp_bundled_fonts::Jost_Regular_ttf,
         pulp_bundled_fonts::Jost_Regular_ttf_size},
        // Jost's other weights, because a family bundled at ONE weight is a
        // family that abandons itself: a weight match refuses a face too far
        // from the request, so a 600 heading fell past the bundle to a
        // platform substitute about 10% wider.
        {"Jost-Medium.ttf", pulp_bundled_fonts::Jost_Medium_ttf,
         pulp_bundled_fonts::Jost_Medium_ttf_size},
        {"Jost-SemiBold.ttf", pulp_bundled_fonts::Jost_SemiBold_ttf,
         pulp_bundled_fonts::Jost_SemiBold_ttf_size},
        {"Jost-Bold.ttf", pulp_bundled_fonts::Jost_Bold_ttf,
         pulp_bundled_fonts::Jost_Bold_ttf_size},
    }};
    return kBlobs;
}

} // namespace pulp::canvas::detail
